// MSB-first (Adafruit GFX) -> LSB-first (XBM, чего ждёт u8g2.drawXBM()) для одного байта
static uint8_t reverseBits(uint8_t b) {
  b = (b & 0xF0) >> 4 | (b & 0x0F) << 4;
  b = (b & 0xCC) >> 2 | (b & 0x33) << 2;
  b = (b & 0xAA) >> 1 | (b & 0x55) << 1;
  return b;
}

// Зацикливает кадры (с начала после последнего), пока не наберётся BOOT_ANIMATION_DURATION_MS.
// Кадры лежат в PROGMEM (8640 байт — не влезли бы в RAM все разом), поэтому каждый кадр
// перед отрисовкой копируется и переворачивается побитно во временный буфер в RAM
void playBootAnimation() {
  uint8_t buf[FRAME_BYTES];
  unsigned long start = millis();
  uint8_t f = 0;
  while (millis() - start < BOOT_ANIMATION_DURATION_MS) {
    for (uint16_t i = 0; i < FRAME_BYTES; i++) {
      buf[i] = reverseBits(pgm_read_byte(&frames[f][i]));
    }
    u8g2.clearBuffer();
    u8g2.drawXBM(BOOT_ANIMATION_X, BOOT_ANIMATION_Y, FRAME_WIDTH, FRAME_HEIGHT, buf);
    u8g2.sendBuffer();
    delay(BOOT_ANIMATION_FRAME_DELAY_MS);
    f = (f + 1) % FRAME_COUNT;
  }
}